import{_ as t,o,c as n,a3 as e}from"./chunks/framework.BlfGB29P.js";const y=JSON.parse('{"title":"Python 抽象与组织","description":"","frontmatter":{"title":"Python 抽象与组织"},"headers":[],"relativePath":"py-agent/foundations/python-abstractions/index.md","filePath":"py-agent/foundations/python-abstractions/index.md","lastUpdated":1785242340000}'),i={name:"py-agent/foundations/python-abstractions/index.md"};function s(r,a,l,h,p,c){return o(),n("div",null,[...a[0]||(a[0]=[e('<h1 id="python-抽象与组织" tabindex="-1">Python 抽象与组织 <a class="header-anchor" href="#python-抽象与组织" aria-label="Permalink to &quot;Python 抽象与组织&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>Python 语言基础解决的是“代码如何表达计算”，本分组继续解决“规模变大以后，行为、状态、文件和失败如何形成清楚边界”。这些知识不是互不相干的高级语法：作用域决定名称来自哪里，函数和类封装行为与状态，模块和包形成代码边界，异常与上下文管理器形成失败和资源边界。</p><h2 id="本分组的作用" tabindex="-1">本分组的作用 <a class="header-anchor" href="#本分组的作用" aria-label="Permalink to &quot;本分组的作用&quot;">​</a></h2><p>Agent 应用会同时包含模型客户端、提示构造、工具实现、数据对象和错误处理。如果所有状态都放在全局名称中、所有逻辑都写在一个文件里、失败只靠返回特殊值表达，程序很快就会难以理解和测试。本分组提供组织这些代码所需的 Python 语言模型，但不提前讲项目环境、类型检查、Pydantic 或异步 I/O。</p><h2 id="学习目标" tabindex="-1">学习目标 <a class="header-anchor" href="#学习目标" aria-label="Permalink to &quot;学习目标&quot;">​</a></h2><p>完成本分组后，你应当能够：</p><ol><li>用 LEGB、绑定规则和闭包解释名称解析结果。</li><li>把函数当作对象传递，并写出保留元数据的装饰器。</li><li>解释一次导入怎样定位、执行和缓存模块。</li><li>用类、实例和方法组织有状态行为，并区分组合与继承。</li><li>用数据类表达字段型领域对象，正确处理默认值、相等性和不可变约束。</li><li>用异常表达失败，让错误沿调用栈保留上下文地传播。</li><li>用上下文管理器保证同步资源在所有退出路径上释放。</li></ol><h2 id="学习顺序" tabindex="-1">学习顺序 <a class="header-anchor" href="#学习顺序" aria-label="Permalink to &quot;学习顺序&quot;">​</a></h2><ol><li><a href="/py-agent/foundations/python-abstractions/scope-closures">作用域与闭包</a></li><li><a href="/py-agent/foundations/python-abstractions/function-objects-decorators">函数对象与装饰器</a></li><li><a href="/py-agent/foundations/python-abstractions/modules-packages-imports">模块、包与导入</a></li><li><a href="/py-agent/foundations/python-abstractions/classes-instances-methods">类、实例与方法</a></li><li><a href="/py-agent/foundations/python-abstractions/dataclasses-domain-objects">数据类与领域对象</a></li><li><a href="/py-agent/foundations/python-abstractions/exceptions-error-propagation">异常与错误传播</a></li><li><a href="/py-agent/foundations/python-abstractions/context-managers-resources">上下文管理与资源</a></li></ol><p>前两篇解释函数周围的名称与包装机制；第三篇把代码扩展到多个文件；第四、五篇组织对象状态；最后两篇处理失败和资源释放。建议初学者按顺序阅读，因为装饰器依赖闭包，数据类依赖类，资源协议又依赖异常传播。</p><h2 id="内容边界" tabindex="-1">内容边界 <a class="header-anchor" href="#内容边界" aria-label="Permalink to &quot;内容边界&quot;">​</a></h2><p>本分组包含 Python 自身的同步抽象机制，不是面向对象编程或标准库百科。描述符、元类、复杂多重继承、自定义导入器、插件系统和异步上下文管理器不在这里展开。</p><p>类型标注、<code>Protocol</code>、JSON、Pydantic、pytest、环境与依赖属于后续“Python 工程与数据”；协程、任务取消和异步资源属于“Python 异步与 HTTP”。文章中的代码用于观察语言规则，不代替概念和 API 说明。</p>',14)])])}const f=t(i,[["render",s]]);export{y as __pageData,f as default};
